<script setup lang="ts">import {ref,onMounted,computed} from 'vue';import {datasets} from '../stores/datasets';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {fixed} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import SpatialMap from '../components/SpatialMap.vue';const name=ref(''),text=ref(''),description=ref(''),selected=ref('demo-dataset');const {error,busy,act}=useTask();onMounted(datasets.load);const data=computed(()=>datasets.items.value.find(r=>r.id===selected.value));async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)text.value=await f.text()}function submit(){act(async()=>{const row=await datasets.create({name:name.value,csv_text:text.value,coordinate_system:'local_meters',description:description.value});selected.value=row.id;name.value='';text.value=''})}</script><template><PageHeading index="01 / 米制采样" title="先核对坐标，再让距离参与计算。" note="CSV列point_id,x,y,value；x/y为同一局部平面米，value为0–100%的含水率。拒绝重复坐标与非有限值，不把经纬度度数当米。"/><div class="two-col"><section><label>采样批次<select v-model="selected"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><Notice :message="datasets.error.value"/><template v-if="data"><SpatialMap :points="data.points"/><p class="method-note">{{data.points.length}}点 · {{data.coordinate_system}} · {{data.description}}</p><div class="table-wrap"><table><thead><tr><th>点ID</th><th>x 米</th><th>y 米</th><th>含水率%</th></tr></thead><tbody><tr v-for="p in data.points.slice(0,16)" :key="p.point_id"><td>{{p.point_id}}</td><td>{{fixed(p.x,2)}}</td><td>{{fixed(p.y,2)}}</td><td>{{fixed(p.value)}}</td></tr></tbody></table></div></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>导入采样批次</h2><label>批次名称<input v-model="name" required minlength="2"></label><p class="method-note">声明坐标系统：local_meters，不作自动投影换算。</p><label>CSV文件<input type="file" accept=".csv" @change="file"></label><label>采样CSV<textarea v-model="text" rows="9" required placeholder="point_id,x,y,value"></textarea></label><label>地块与测量说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并保存采样</button></form></div></template>
